from pathlib import Path
import base64,html,json
items=[('other-390','Other · 390 × 844','Actual checked radio state, zero axe violations and visible Next.'),('other-375','Other · 375 × 667','Typed answer and Next remain above the raised navigation orb.'),('general-reveal','General oracle · model authored','Real local model writes the context cards and picks the future sentence.'),('general-why','General oracle · grounded explanation','Exact supplied context and an explicit continuity assumption.'),('self-harm-redirect','Safety · support link','Kind redirect and a support directory link, no prediction.'),('reveal-small-why','Small reveal · explanation','375 × 667, scrolling explanation.'),('reveal-small-actions','Small reveal · reachable actions','Scrolling reaches Share and check-back controls.'),('share-actions','Share · export actions','Actual preview plus reachable export controls.'),('explore','Explore · seeded prompts','One topic per invitation; no fabricated popularity.'),('paywall-purchased','Plans · simulated purchase','Explicit no-payment confirmation.'),('home','Home · one invitation','the glass orb leads; explicit Ask and permanent center tab reach the same action.'),('ask','Ask · your own question','visible label, multiline text and voice alternative.'),('question-1','Questions · default','one question, Other, disabled Next until selected.'),('selected-1','Questions · selected','cyan ring and star convey selection without relying only on color.'),('selected-2','Questions · Other','a typed answer stays editable until Next.'),('research','Research · active','Motion: honest operation, no fabricated percent complete.'),('long-wait','Research · longer wait','Recovery: eight-second status update, navigation remains available.'),('timeout','Recovery · timeout','Retry or edit; no prediction or credit charge.'),('network-error','Recovery · offline','Answers retained; retry repeats the same request.'),('blocked','Safety · redirect','Kind alternative, no saved sensitive reading or charge.'),('reveal','Reveal · settled','definitive sentence plus visible speculative context.'),('why','Reveal · explanation','supplied facts, assumptions, dated headline leads; focus stays on disclosure.'),('share','Share · private preview','private question and facts omitted.'),('exported-card','Share · actual artifact','1080 × 1920. Critical content remains inside the conservative central safe region.'),('history','History · populated','Persisted reading reopens after browser reload.'),('history-empty','History · empty','No invented past predictions; invitation to ask.'),('history-yes','History · came true','User-authored outcome, not an accuracy claim by the app.'),('history-no','History · another path','A prediction can be marked wrong and remains visible.'),('knowledge','You · remembered facts','visible editable knowledge with human labels.'),('knowledge-edit','You · edit','Edit and Forget affect the next plan.'),('knowledge-empty','You · empty','Explains what the Ball will remember.'),('paywall','Plans · test offers','prices and periods, no discount theater, no payment taken.'),('restore-preview','Plans · restore','Honest mock-state response.'),('friend','Friend · separate context','Friend answers cannot enter owner knowledge.'),('voice-fallback','Voice · unavailable','Typing remains available without microphone permission.'),('keyboard-focus','Keyboard · visible focus','Cyan focus indication and scrollable input.'),('money-10','Numeric flow · tenth card','Ten distinct numerical inputs, no padding questions.'),('money-reveal','Numeric flow · result','Deterministic arithmetic and constrained model rendering.'),('large-home','Large text · Home','375 × 667 at 200% app text. Early Ask; full tab labels remain visible and retain accessible names.'),('large-question','Large text · card','No line clamps; scroll to remaining content.'),('large-reveal','Large text · reveal','Speculative label precedes headline; decorative orb shrinks to 96 pt.')]
fonts={n:base64.b64encode(Path(p).read_bytes()).decode() for n,p in [('Display','node_modules/@expo-google-fonts/cormorant-garamond/500Medium/CormorantGaramond_500Medium.ttf'),('Body','node_modules/@expo-google-fonts/dm-sans/400Regular/DMSans_400Regular.ttf')]}
css=''.join(f'@font-face{{font-family:{n};src:url(data:font/ttf;base64,{b})}}' for n,b in fonts.items())+'''body{margin:0;padding:32px;background:#0B0620;color:#F7F1FF;font:16px/1.5 Body,sans-serif}h1,h2{font-family:Display,serif;font-weight:500}h1{font-size:56px;line-height:1.05;max-width:680px}h2{font-size:34px}p{max-width:900px;color:#C4B8D8}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:32px}.panel{padding:24px;border:1px solid #66537F;border-radius:20px;margin:24px 0;background:#160F30}.swatches{display:flex;gap:20px;flex-wrap:wrap}.swatch i{display:block;width:72px;height:40px;border:1px solid #66537F;border-radius:8px}figure{margin:0}figure img{width:100%;border:1px solid #66537F;border-radius:18px}figcaption{padding:12px 0;color:#C4B8D8}b{color:#F5C76B}a{color:#5CE1E6}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #49365F;padding:12px}.film{display:flex;gap:12px;overflow:auto}.film figure{flex:0 0 180px}video{max-width:390px;width:100%;border-radius:18px}.alternatives{display:flex;gap:24px}.mini{padding:20px;background:#25193F;border:1px solid #66537F;flex:1}.cards{display:flex;gap:5px}.cards i{width:20%;height:60px;background:#66537F;border-radius:5px}.orb{margin:auto;width:70px;height:70px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#A77BFF,#2A1458 60%,#0B0620);border:1px solid #A77BFF}.bars i{display:block;height:10px;background:#66537F;margin:7px}'''
body='<h1>A tiny observatory in your pocket.</h1><p>Review the visual decisions, then the observed states. Captures are from the real local Expo prototype at 390 × 844 unless labeled. This is browser evidence; native device validation remains deferred.</p><section class="panel"><h2>The visual grammar</h2><div class="swatches">'
for name,color in [('Ink','#0B0620'),('Violet','#2A1458'),('Orb','#A77BFF'),('Ice','#5CE1E6'),('Gold','#F5C76B')]:body+=f'<div class="swatch"><i style="background:{color}"></i>{name}<br>{color}</div>'
body+='</div><h2>Your future has a little mystery.</h2><p>Display: Cormorant Garamond 500, 36/40. Interface: DM Sans, 16/24. Metadata: 13/19. Gold carries action; cyan carries selection and links.</p><p>Spacing rhythm: 8 / 12 / 16 / 24 / 32 pt. Page inset 24 pt. Action ≥52 pt. Other targets ≥44 pt. Cards expand with content; the page scrolls above a permanent navigation bar.</p></section><section class="panel"><h2>Composition choice</h2><div class="alternatives"><div class="mini"><div class="cards"><i></i><i></i><i></i></div><b>Rejected: tarot deck</b><p>Implies card reading rather than one oracle.</p></div><div class="mini"><div class="bars"><i></i><i></i><i></i></div><b>Rejected: dashboard</b><p>Prioritizes old readings over the invitation.</p></div><div class="mini"><div class="orb"></div><b>Chosen: observatory</b><p>One luminous object and a direct question.</p></div></div></section>'
body+='<section class="panel"><h2>Motion and the reveal</h2><p>Screen entrance: 180 ms cubic-out, 8 pt rise. Reveal: thin gold rim, a separate reveal glow rising from 0 to 35% opacity over 250 ms, clearing over 450 ms. Headline and speculative label fade together from 200–800 ms. Reduced motion removes all automatic movement.</p><div class="film">'
for ms in [0,200,300,400,600,700,800]:
 p=Path(f'docs/evidence/reveal-frame-{ms}.png')
 if p.exists():body+=f'<figure><img src="../evidence/{p.name}" alt="Observed reveal frame {ms}"><figcaption>{ms} ms capture offset</figcaption></figure>'
body+='</div><p>Capture offsets begin when the reveal control appears; browser scheduling means these are observed frames, not exact animation keyframes.</p>'
for file,title in [('flow-recording.webm','Historical observed app flow')]:
 if Path('docs/evidence/'+file).exists():body+=f'<h3>{title}</h3><video controls preload="metadata" src="../evidence/{file}"></video>'
body+='</section><section class="panel"><h2>State coverage and remaining checks</h2><table><tr><th>Surface</th><th>Observed</th><th>Deferred</th></tr><tr><td>Ask / generation</td><td>Typed, Other, known skips, adaptive cards, offline retry, 60-second timeout, sensitive redirect</td><td>Physical microphone, native keyboard</td></tr><tr><td>Persistence / sharing</td><td>Reload, edit/forget, friend isolation, outcome, PNG</td><td>Native share sheet and destination overlays</td></tr><tr><td>Accessibility</td><td>200% app text, reduced motion, keyboard focus, automated axe scan</td><td>VoiceOver, native Dynamic Type</td></tr><tr><td>Accounts / commerce</td><td>Local anonymous Supabase, RLS, mock pack and restore; native boundary tests</td><td>Configured Apple and RevenueCat sandbox device flow</td></tr></table><p>No open product decision is required to inspect this prototype. Independent phase grades and unresolved quality findings remain in <a href="../grades/">the grade artifacts</a>; no unearned 9/10 is claimed.</p></section><h2>Observed anatomy and states</h2><main class="grid">'
items += [('daily-cap','Daily allowance used','Ask opens the explicit test-mode paywall; no model call is started.'),('share-export-failure','Export recovery','Injected HTTP 500 produces a recoverable export message.'),('forget-undo','Forget with Undo','A forgotten fact can be restored before navigation.')]
for name,title,caption in items:
 if Path(f'docs/evidence/{name}.png').exists():body+=f'<figure><img src="../evidence/{name}.png" alt="{html.escape(title)}"><figcaption><b>{html.escape(title)}</b><br>{html.escape(caption)}</figcaption></figure>'
body+='</main><p><a href="system.md">Components and screen specification</a> · <a href="motion.md">Motion authority</a> · <a href="contrast.json">Token contrast pairs</a> · <a href="../evidence/screen-contrast.json">Measured gradient screenshots</a></p>'
Path('docs/design/review.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Crystal Ball · annotated review</title><style>'+css+'</style>'+body+'</html>')
